import pickle
import numpy as np
import scipy
with open('/holdout_task/public_helmholtz_cases.pkl','rb') as f:
    data=pickle.load(f)
def show(x,d=0):
    if isinstance(x,dict):
        print('dict')
        for k,v in x.items():
            print(' '*d+str(k)+': ',end=''); show(v,d+2)
